// Guardrails Lite as a Claude Code mod (Claude Code 2.1.287+).
import { evaluate } from './lite-core.mjs'

const RESERVED = new Set(['tool', 'tool_use_id', 'consent', 'agentId'])

/** Turn a mod tool.call event into the {tool_name, tool_input} shape the core takes. */
export function toHookInput(e) {
  const tool_input = {}
  for (const k of Object.keys(e ?? {})) if (!RESERVED.has(k)) tool_input[k] = e[k]
  return { tool_name: String(e?.tool ?? ''), tool_input }
}

/** Returns the deny reason, or null to let the call through. */
export function decide(e) {
  const d = evaluate(toHookInput(e))
  return d ? d.reason : null
}

export function register(on) {
  on('tool.call', async ($, e, next) => {
    let reason
    try {
      reason = decide(e)
    } catch (err) {
      // Fail closed: if the check itself errors, deny the call rather than let it through unchecked.
      const msg = err && err.message ? err.message : String(err)
      process.stderr.write(`Guardrails Lite: internal error while checking a tool call, denying it: ${msg}\n`)
      return { deny: `Guardrails Lite: internal error while checking this call (${msg}), so it was denied. Ask the user to run it, or report the error.` }
    }
    if (reason) return { deny: reason }
    return next(e)
  }).catch(onHookFailure)
}

/**
 * .catch handler: Claude Code calls it when the tool.call hook above throws, times out
 * or returns a bad shape. Before next ran, deny the call; after, keep the result next produced.
 */
export async function onHookFailure($, e, next) {
  if (next && next.called) return next(e)
  const kind = (next && next.error && next.error.kind) || 'unknown'
  return { deny: `Guardrails Lite: the check failed (${kind}), so this call was denied. Ask the user to run it, or report the error.` }
}

