// Guardrails Lite: pure decision logic. No dependencies. Node 18+.
// Three checks: secret .env reads, git force push, rm -rf on /, ~ or $HOME.
// Every check is linear-time: split on separators/whitespace, then Set lookups,
// startsWith and simple anchored regexes with no nested quantifiers.
// Inputs over MAX_INPUT (64 K characters) are denied unchecked so a huge input can't stall the check.

export const MAX_INPUT = 64 * 1024

const READERS = new Set(['cat', 'less', 'more', 'head', 'tail', 'bat', 'nl', 'strings', 'grep', 'rg', 'awk', 'sed', 'cp', 'scp', 'base64', 'xxd', 'source', '.'])

/** True for .env, .env.local, path/to/.env.production; false for .env.example/.sample/.template. */
export function isSecretEnvName(name) {
  let t = String(name).replace(/\\/g, '/').replace(/^@+/, '').replace(/^["']+|["']+$/g, '')
  const slash = t.lastIndexOf('/')
  if (slash >= 0) t = t.slice(slash + 1)
  if (t === '.env' || t === '.env*' || t === '.env.*') return true
  if (!t.startsWith('.env.')) return false
  const parts = t.slice(5).split('.')
  if (parts.some((p) => !/^[\w*-]+$/.test(p))) return false
  return !['example', 'sample', 'template'].includes(parts[parts.length - 1].toLowerCase())
}

function segments(cmd) {
  return cmd.split(/[;&|\n]+/).map((s) => s.trim().split(/\s+/).filter(Boolean))
}

function forcePush(w) {
  const gp = w.findIndex((x, i) => x === 'git' && w[i + 1] === 'push')
  if (gp < 0) return false
  return w.slice(gp + 2).some((x) => x === '-f' || x.startsWith('--force') || (x.startsWith('-') && !x.startsWith('--') && x.includes('f')) || (x.startsWith('+') && x.length > 1))
}

const RM_TARGETS = new Set(['/', '/*', '~', '~/', '~/*', '$HOME', '$HOME/', '$HOME/*', '${HOME}', '${HOME}/', '${HOME}/*', '"$HOME"', '"${HOME}"'])
function rmRecursiveRootOrHome(w) {
  const r = w.indexOf('rm')
  if (r < 0) return false
  const args = w.slice(r + 1)
  const recursive = args.some((x) => x === '--recursive' || (x.startsWith('-') && !x.startsWith('--') && /[rR]/.test(x)))
  return recursive && args.some((x) => RM_TARGETS.has(x))
}

function readsSecretFile(w) {
  const r = w.findIndex((x) => READERS.has(x))
  return r >= 0 && w.slice(r + 1).some(isSecretEnvName)
}

const deny = (reason) => ({ decision: 'deny', reason })

/**
 * @param {{tool_name: string, tool_input: Record<string, any>}} input
 * @returns {{decision: 'deny', reason: string} | null}
 */
export function evaluate(input) {
  const tool = String(input?.tool_name ?? '')
  const ti = input?.tool_input ?? {}

  if (tool === 'Read' || tool === 'Grep' || tool === 'Glob') {
    const targets = [ti.file_path, ti.path, tool === 'Glob' ? ti.pattern : undefined, ti.glob].filter((x) => typeof x === 'string')
    for (const t of targets) {
      if (t.length > MAX_INPUT) return deny('Guardrails Lite: the path or pattern is too large to check.')
      if (t.split(/[\s,{}]+/).some(isSecretEnvName)) return deny(`Guardrails Lite: reading ${t} is blocked because .env files hold secrets. Use .env.example for variable names, or ask the user for the specific value.`)
    }
    return null
  }

  if (tool === 'Bash') {
    const cmd = typeof ti.command === 'string' ? ti.command : ''
    if (cmd.length > MAX_INPUT) return deny(`Guardrails Lite: the command is over ${MAX_INPUT / 1024} K characters, too large to check.`)
    for (const w of segments(cmd)) {
      if (forcePush(w)) return deny('Guardrails Lite: force push needs the user\'s explicit approval. Ask the user to run it.')
      if (rmRecursiveRootOrHome(w)) return deny('Guardrails Lite: recursive rm on /, ~ or $HOME is blocked. Ask the user to run it.')
      if (readsSecretFile(w)) return deny('Guardrails Lite: this command would print or copy a secret .env file. Use .env.example instead.')
    }
  }
  return null
}

